// Sentientia LMS PWA — subscribe module — Phase B.2.b.
// IMPORTANT: This file is HAND-BUILT ES5 with a NAMED DEFINE.
// Do not run a grunt build that overwrites this with anonymous define()
// until grunt is properly configured for the plugin. The named define
// is required because Moodle bundles AMD modules into a single first/
// boot chunk; anonymous define() inside that chunk has no name and
// breaks every other module's loading.
// (Lesson learned 2026-05-20: see PROJECT-STATE.md "AMD pipeline fix".)
define('local_sentientia_pwa/subscribe', ['core/ajax', 'core/notification'], function(Ajax, Notification) {
    'use strict';

    var ROOT_SELECTOR = '.sentientia-pwa-subscribe';
    var BUTTON_ID = 'sentientia-pwa-subscribe-btn';

    function urlBase64ToUint8Array(base64String) {
        var padding = '='.repeat((4 - base64String.length % 4) % 4);
        var base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
        var rawData = window.atob(base64);
        var outputArray = new Uint8Array(rawData.length);
        for (var i = 0; i < rawData.length; ++i) {
            outputArray[i] = rawData.charCodeAt(i);
        }
        return outputArray;
    }

    function isPushSupported() {
        return 'serviceWorker' in navigator
            && 'PushManager' in window
            && 'Notification' in window;
    }

    function setButtonState(button, state, labels) {
        if (!button) { return; }
        button.disabled = false;
        button.classList.remove('btn-primary', 'btn-outline-secondary', 'btn-secondary', 'btn-danger');
        if (state === 'subscribed') {
            button.textContent = labels.unsubscribe;
            button.dataset.action = 'unsubscribe';
            button.classList.add('btn-outline-secondary');
        } else if (state === 'unsubscribed') {
            button.textContent = labels.subscribe;
            button.dataset.action = 'subscribe';
            button.classList.add('btn-primary');
        } else if (state === 'unsupported') {
            button.disabled = true;
            button.textContent = labels.unsupported;
            button.classList.add('btn-secondary');
        } else if (state === 'permission_denied') {
            button.disabled = true;
            button.textContent = labels.denied;
            button.classList.add('btn-danger');
        }
    }

    function handleSubscribe(button, vapidKey, labels) {
        if (Notification.permission === 'denied') {
            setButtonState(button, 'permission_denied', labels);
            return;
        }
        Notification.requestPermission().then(function(permission) {
            if (permission !== 'granted') {
                setButtonState(button, 'permission_denied', labels);
                return null;
            }
            return navigator.serviceWorker.ready.then(function(registration) {
                return registration.pushManager.subscribe({
                    userVisibleOnly: true,
                    applicationServerKey: urlBase64ToUint8Array(vapidKey)
                });
            }).then(function(subscription) {
                var sub = subscription.toJSON();
                var keys = sub.keys || {};
                return Ajax.call([{
                    methodname: 'local_sentientia_pwa_save_subscription',
                    args: {
                        endpoint: sub.endpoint,
                        p256dh: keys.p256dh || '',
                        authkey: keys.auth || '',
                        useragent: navigator.userAgent.substring(0, 250)
                    }
                }])[0];
            }).then(function() {
                setButtonState(button, 'subscribed', labels);
            });
        }).catch(function(err) {
            setButtonState(button, 'unsubscribed', labels);
            Notification.exception(err);
        });
    }

    function handleUnsubscribe(button, labels) {
        navigator.serviceWorker.ready.then(function(registration) {
            return registration.pushManager.getSubscription();
        }).then(function(subscription) {
            if (!subscription) {
                setButtonState(button, 'unsubscribed', labels);
                return null;
            }
            var endpoint = subscription.endpoint;
            return subscription.unsubscribe().then(function() {
                return Ajax.call([{
                    methodname: 'local_sentientia_pwa_delete_subscription',
                    args: {endpoint: endpoint}
                }])[0];
            });
        }).then(function() {
            setButtonState(button, 'unsubscribed', labels);
        }).catch(function(err) {
            Notification.exception(err);
        });
    }

    function bindClick(button, vapidKey, labels) {
        button.addEventListener('click', function(ev) {
            ev.preventDefault();
            var action = button.dataset.action;
            button.disabled = true;
            if (action === 'subscribe') {
                handleSubscribe(button, vapidKey, labels);
            } else if (action === 'unsubscribe') {
                handleUnsubscribe(button, labels);
            }
        });
    }

    function init() {
        var root = document.querySelector(ROOT_SELECTOR);
        if (!root) { return; }
        var button = document.getElementById(BUTTON_ID);
        if (!button) { return; }

        var labels = {
            subscribe: button.dataset.subscribeLabel || 'Enable notifications',
            unsubscribe: button.dataset.unsubscribeLabel || 'Disable notifications',
            unsupported: button.dataset.unsupportedLabel || 'Not supported',
            denied: button.dataset.deniedLabel || 'Notifications blocked'
        };

        if (!isPushSupported()) {
            setButtonState(button, 'unsupported', labels);
            return;
        }

        if (Notification.permission === 'denied') {
            setButtonState(button, 'permission_denied', labels);
            return;
        }

        var vapidKey = root.dataset.vapidPublicKey;
        if (!vapidKey) {
            setButtonState(button, 'unsupported', labels);
            return;
        }

        navigator.serviceWorker.ready.then(function(registration) {
            return registration.pushManager.getSubscription();
        }).then(function(existing) {
            setButtonState(button, existing ? 'subscribed' : 'unsubscribed', labels);
            bindClick(button, vapidKey, labels);
        }).catch(function() {
            setButtonState(button, 'unsubscribed', labels);
            bindClick(button, vapidKey, labels);
        });
    }

    return {
        init: init
    };
});
